<script setup lang="ts">
import { Plus, Radio, Clapperboard, HardDrive, Workflow, ArrowUpRight, ArrowRight, ScanLine, AudioLines, Sparkles, CircleCheck, CircleDot } from '@lucide/vue'
import type { Dashboard, Streamer } from '~/types'
const { data, error, status, refresh } = await useFetch<Dashboard>('/api/dashboard', { key: 'dashboard', timeout: 8000 })
usePolling(refresh)
const formOpen = ref(false)
const editing = ref<Streamer | null>(null)
const selectedClip = ref<string | null>(null)
const stats = computed(() => [
  { label: 'Aktive Streams', value: data.value?.stats.recording ?? '—', sub: data.value ? `${data.value.stats.streamers} Kanäle auf deiner Watchlist` : 'Deine Kanäle im Blick', icon: Radio, accent: true },
  { label: 'Clips heute', value: data.value?.stats.clips_today ?? '—', sub: data.value ? `${data.value.stats.clips_ready} Clips in deiner Bibliothek` : 'Jeder gute Moment zählt', icon: Clapperboard },
  { label: 'In Verarbeitung', value: data.value?.stats.pending ?? '—', sub: data.value?.stats.failed ? `${data.value.stats.failed} Aufträge benötigen Aufmerksamkeit` : 'Aufnehmen, schneiden, sichern', icon: Workflow },
  { label: 'S3 Speicher', value: data.value ? bytes(data.value.stats.stored_bytes) : '—', sub: 'Deine Highlights, privat gespeichert', icon: HardDrive },
])
function edit(streamer: Streamer) { editing.value = streamer; formOpen.value = true }
function add() { editing.value = null; formOpen.value = true }
</script>
<template>
  <div>
    <div class="mb-8 flex flex-col justify-between gap-5 sm:flex-row sm:items-center"><div><div class="eyebrow mb-2 flex items-center gap-2"><span class="size-1.5 rounded-full bg-lime-300" />Dein persönliches Highlight-Studio</div><h1 class="page-title">Lass keinen Moment liegen<span class="text-lime-300">.</span></h1><p class="mt-2 text-sm text-studio-400">Deine Streamer. Ihre besten Momente. Automatisch gesammelt.</p></div><button class="btn btn-primary self-start sm:self-auto" @click="add"><Plus :size="17" />Streamer hinzufügen</button></div>
    <div class="mb-8 grid grid-cols-2 gap-3 xl:grid-cols-4 xl:gap-4"><div v-for="stat in stats" :key="stat.label" class="panel relative overflow-hidden p-5"><div class="flex items-center justify-between"><span class="text-xs text-studio-400">{{ stat.label }}</span><component :is="stat.icon" :size="16" :class="stat.accent ? 'text-lime-300' : 'text-studio-400'" /></div><div class="mt-4 text-3xl font-semibold tracking-tight" :class="stat.accent ? 'text-lime-300' : 'text-zinc-100'">{{ stat.value }}</div><p class="mt-2 text-[10px] leading-relaxed text-studio-400">{{ stat.sub }}</p><div v-if="stat.accent" class="absolute bottom-0 left-0 h-0.5 w-full bg-gradient-to-r from-lime-300/60 to-transparent" /></div></div>
    <ConnectionError v-if="error" @retry="refresh" />
    <div v-else-if="status === 'pending' && !data" class="panel flex animate-pulse items-center justify-center p-16 text-sm text-studio-400">Studio wird geladen …</div>
    <template v-else>
      <section class="mb-9"><div class="mb-4 flex items-center justify-between"><h2 class="flex items-center gap-2.5 text-base font-semibold"><Radio :size="17" class="text-lime-300" />Deine Watchlist<span class="rounded-md bg-studio-800 px-1.5 py-0.5 text-[10px] font-normal text-studio-400">{{ data?.streamers.length || 0 }}</span></h2><NuxtLink to="/streamers" class="flex items-center gap-1.5 text-xs text-studio-400 hover:text-lime-300">Alle Streamer<ArrowUpRight :size="14" /></NuxtLink></div>
        <div v-if="data?.streamers.length" class="grid gap-4 md:grid-cols-2 xl:grid-cols-3"><StreamerCard v-for="streamer in data.streamers.slice(0, 3)" :key="streamer.id" :streamer="streamer" @edit="edit" @changed="refresh" /></div>
        <div v-else class="panel relative overflow-hidden p-7 sm:p-9"><div class="absolute -right-8 -top-16 size-64 rounded-full bg-lime-300/3 blur-3xl" /><div class="relative grid items-center gap-8 md:grid-cols-[1fr_260px]"><div><span class="mb-5 inline-flex rounded-lg border border-lime-300/20 bg-lime-300/5 p-2.5 text-lime-300"><ScanLine :size="23" /></span><h3 class="text-xl font-semibold tracking-tight">Der nächste gute Clip wartet schon.</h3><p class="mt-2 max-w-md text-sm leading-relaxed text-studio-400">Füge deinen ersten Streamer hinzu. Wir halten den Puffer bereit und sichern auffällige Momente für dich.</p><button class="mt-5 flex items-center gap-2 text-sm font-semibold text-lime-300 hover:text-lime-200" @click="add">Watchlist starten<ArrowRight :size="15" /></button></div><div class="space-y-5 border-l divider pl-7"><div v-for="(step, i) in [{ icon: Radio, title: 'Streamer hinzufügen', text: 'Ein Kanalname genügt.' }, { icon: AudioLines, title: 'Momente erkennen', text: 'Audioanalyse auf deinem Worker.' }, { icon: Clapperboard, title: 'Highlights einsammeln', text: 'Als MP4 in deinem S3-Bucket.' }]" :key="step.title" class="flex gap-3"><component :is="step.icon" :size="17" class="mt-0.5 shrink-0 text-studio-400" /><div><p class="text-xs font-medium"><span class="mr-1 text-studio-400">0{{ i + 1 }}</span> {{ step.title }}</p><p class="mt-1 text-[11px] text-studio-400">{{ step.text }}</p></div></div></div></div></div>
      </section>
      <div class="grid gap-7 xl:grid-cols-[1fr_310px]">
        <section><div class="mb-4 flex items-center justify-between"><h2 class="flex items-center gap-2.5 text-base font-semibold"><Sparkles :size="17" class="text-lime-300" />Frisch eingefangen</h2><NuxtLink to="/clips" class="flex items-center gap-1.5 text-xs text-studio-400 hover:text-lime-300">Zur Bibliothek<ArrowUpRight :size="14" /></NuxtLink></div><div v-if="data?.clips.length" class="grid gap-4 sm:grid-cols-2"><ClipCard v-for="clip in data.clips.slice(0, 4)" :key="clip.id" :clip="clip" @open="selectedClip = $event" @changed="refresh" /></div><div v-else class="panel flex min-h-[250px] flex-col items-center justify-center border-dashed p-8 text-center"><div class="mb-4 flex size-12 items-center justify-center rounded-xl bg-studio-800"><Clapperboard :size="22" class="text-studio-400" /></div><h3 class="text-sm font-medium">Hier landen deine Highlights.</h3><p class="mt-2 max-w-xs text-xs leading-relaxed text-studio-400">Sobald der erste Moment erkannt und gespeichert wurde, erscheint er genau hier.</p></div></section>
        <section><h2 class="mb-4 flex h-6 items-center gap-2.5 text-base font-semibold"><CircleDot :size="17" class="text-studio-400" />Studio-Aktivität</h2><div class="panel min-h-[250px] p-5"><div v-if="data?.activity.length" class="space-y-5"><div v-for="event in data.activity" :key="event.id" class="flex gap-3"><span class="mt-0.5 flex size-6 shrink-0 items-center justify-center rounded-full" :class="event.kind === 'clip' ? 'bg-lime-300/10 text-lime-300' : 'bg-studio-800 text-studio-400'"><CircleCheck v-if="event.kind === 'clip'" :size="12" /><Radio v-else :size="12" /></span><div><p class="text-[11px] leading-relaxed text-zinc-300">{{ event.message }}</p><p class="mt-1 text-[9px] text-studio-400">{{ dateTime(event.created_at) }}</p></div></div></div><div v-else class="py-12 text-center"><span class="mx-auto mb-4 block size-2 rounded-full bg-studio-700" /><p class="text-xs text-studio-400">Noch ganz ruhig hier.</p><p class="mt-1 text-[10px] text-studio-400/70">Dein Studio ist startklar.</p></div></div></section>
      </div>
    </template>
    <StreamerForm :open="formOpen" :streamer="editing" @close="formOpen = false" @saved="refresh" /><ClipPlayer :clip-id="selectedClip" @close="selectedClip = null" @changed="refresh" />
  </div>
</template>
